test.fill_query:
INSERT INTO lower_upper_utf8_mixed_ascii
SELECT
    ascii,
    if(number % 1000 = 0, unicode, ascii),
    if(number < 500, unicode, ascii),
    if(number % 10 = 0, unicode, ascii),
    if(number % 2 = 0, unicode, ascii),
    unicode,
    ascii_short,
    if(number % 1000 = 0, unicode_short, ascii_short),
    if(number % 2 = 0, unicode_short, ascii_short),
    if(cityHash64(number) % 2 = 0, unicode_short, ascii_short),
    unicode_short,
    if(number % 2 = 0, unicode_16, ascii_16),
    unicode_16,
    unicode_16_late,
    if(number % 2 = 0, unicode_16_late, ascii_16),
    if(number % 65536 >= 65472, unicode, ascii)
FROM
(
    SELECT
        number,
        concat(
            repeat('AbCdEfGhIjKlMnOpQrStUvWxYz0123456789', 3),
            rightPad(toString(number), 20, 'x')) AS ascii,
        concat(
            repeat('AbCdEfGhIjKlMnOpQrStUvWxYz0123456789', 3),
            'é',
            rightPad(toString(number), 18, 'x')) AS unicode,
        'Ab' AS ascii_short,
        'AbCdEfGhIjKlMnOp' AS ascii_16,
        'é' AS unicode_short,
        repeat('é', 8) AS unicode_16,
        concat(repeat('A', 14), 'é') AS unicode_16_late
    FROM numbers(500000)
)
